with kept_keys as (select country from sessions intersect all select country from sessions where browser not in ('Chrome', 'Safari')), reconciled as (select s.* from sessions s inner join kept_keys k on s.country = k.country) select date_trunc('year', started_at) as year_start, customer_id, count(*) as row_count, size(collect_set(country)) as num_countries, count(distinct id) as distinct_ids from reconciled group by grouping sets ((date_trunc('year', started_at), customer_id), (date_trunc('year', started_at))) order by num_countries desc nulls first
